// M012-B: real HTML and CSP generated by handlePreparationDemo, local HTTP only.
// A's exact wire protocol is exercised against an isolated fixture, NOT real D1.
import assert from 'node:assert/strict';
import {createServer} from 'node:http';
import {pbkdf2Sync,createHmac,randomUUID} from 'node:crypto';
import {chromium} from 'playwright';
import {handlePreparationDemo} from '../migration/cloudflare/editor-demo-preparation-page.mjs';
const DB={prepare(sql){return {bind(){return {async all(){
 return {results:sql.includes('FROM celebrations_celebrations')?[{id:41,archangel:'Gabriel',year:'2026',status:'published'}]:[]};
}}}}}};
const generated=await handlePreparationDemo(new Request('https://www.ronde-des-archanges-universelle.eu/__editor/demo-preparation'),{DB});
assert.equal(generated.status,200);
const html=await generated.text();
assert.match(html,/data-tab="members-spaces"/);
assert.doesNotMatch(html,/data-admin="members-spaces"/);
const csp=generated.headers.get('content-security-policy');
assert.ok(csp.includes("script-src 'nonce-"));
const people=Array.from({length:126},(_,i)=>({id:'person:550e8400-e29b-41d4-a716-'+String(i+1).padStart(12,'0'),name:i===125?'Camille Extrême':'Personne '+i,emailNormalized:'person'+String(i).padStart(3,'0')+'@example.test',revision:0}));
const types=[{id:'member-type:choir',name:'Chorale',revision:0,disabled:false}];
const password='local-test-only-password',salt='local-test-salt';
const derived=pbkdf2Sync(password,salt,180000,32,'sha256').toString('hex');
let unavailable=false,failDirectory=false,denyDirectory=false,requests=[],challenges=new Set(),tokens=new Set();
const json=(res,code,data)=>res.writeHead(code,{'content-type':'application/json','cache-control':'no-store'}).end(JSON.stringify(data));
const server=createServer(async(req,res)=>{
 const url=new URL(req.url,'http://'+req.headers.host);
 if(url.pathname==='/'||url.pathname==='/__editor/demo-preparation'){
  res.writeHead(200,{'content-type':'text/html; charset=utf-8','content-security-policy':csp}).end(html);return;
 }
 if(url.pathname==='/api/admin/editor-session'){
  let raw='';for await(const part of req)raw+=part;
  const body=JSON.parse(raw);requests.push({path:url.pathname,action:body.action,auth:req.headers.authorization});
  if(unavailable)return json(res,404,{ok:false});
  if(body.action==='challenge'){
   assert.equal(req.headers.authorization,undefined);
   const challenge=randomUUID();challenges.add(challenge);
   return json(res,200,{ok:true,salt,challenge,iterations:180000,expires_in:120});
  }
  if(body.action==='login'){
   assert.equal(req.headers.authorization,undefined);
   assert.deepEqual(Object.keys(body).sort(),['action','challenge','response']);
   const expected=createHmac('sha256',derived).update('celebrations-admin-login-v1:'+url.origin+':'+body.challenge).digest('hex');
   if(!challenges.delete(body.challenge)||body.response!==expected)return json(res,401,{ok:false});
   const token=randomUUID();tokens.add(token);
   return json(res,200,{ok:true,token,email:'admin@celebrations.local',expires_at:new Date(Date.now()+3600000).toISOString()});
  }
  if(body.action==='logout'){
   tokens.delete(req.headers.authorization?.slice(7));
   return json(res,200,{ok:true});
  }
  if(body.action==='session'&&tokens.has(req.headers.authorization?.slice(7)))return json(res,200,{ok:true,expires_at:new Date(Date.now()+3600000).toISOString()});
  return json(res,401,{ok:false});
 }
 if(url.pathname==='/api/admin/member-directory'){
  const action=url.searchParams.get('action');
  requests.push({path:url.pathname,action,method:req.method,auth:req.headers.authorization});
  if(!tokens.has(req.headers.authorization?.slice(7))||denyDirectory)return json(res,401,{ok:false});
  if(failDirectory)return json(res,503,{ok:false});
  if(req.method==='POST')return json(res,400,{ok:false});
  let data;
  if(action==='snapshot'){
   const search=(url.searchParams.get('search')||'').toLowerCase(),cursor=url.searchParams.get('cursor')||'';
   const filtered=people.filter(p=>p.emailNormalized>cursor&&[p.name,p.emailNormalized].some(x=>x.toLowerCase().includes(search)));
   const members=filtered.slice(0,50);
   data={members,types,memberships:[],pages:[],spaces:[],enrollments:[],hasMorePeople:filtered.length>50,nextCursor:filtered.length>50?members.at(-1).emailNormalized:null};
  }else if(action==='person_detail'){
   const person=people.find(p=>p.id===url.searchParams.get('personId'));data={person,types:[],celebrations:[],enrollments:[]};
  }else if(action==='pending_claims')data=[];
  else return json(res,400,{ok:false});
  return json(res,200,{ok:true,data});
 }
 // Existing editorial endpoints are intentionally read-only/unavailable.
 res.writeHead(404).end();
});
await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));
let browser;
try{
 browser=await chromium.launch({headless:true});
 for(const width of [1440,390,320]){
  requests=[];unavailable=false;failDirectory=false;denyDirectory=false;
  const page=await browser.newPage({viewport:{width,height:850},isMobile:width<500,hasTouch:width<500});
  const errors=[];page.on('pageerror',e=>errors.push(String(e)));
  await page.route('**/*',route=>new URL(route.request().url()).hostname==='127.0.0.1'?route.continue():route.abort());
  await page.goto('http://127.0.0.1:'+server.address().port+'/__editor/demo-preparation');
  const tab=key=>page.locator('[data-tab="'+key+'"]');
  await tab('members-spaces').click();
  await page.getByRole('heading',{name:'Membres et espaces',exact:true}).waitFor();
  await page.locator('.member-session-box').getByText('Non connecté à D1',{exact:true}).waitFor();
  await page.getByText(/Administration indisponible : Non connecté à D1/).waitFor();
  assert.equal(requests.length,0);
  assert.equal(await page.locator('#save-btn').isVisible(),false);
  const login=async()=>{
   await page.getByLabel('Mot de passe administrateur D1').fill(password);
   await page.getByRole('button',{name:'Se connecter à D1'}).click();
  };
  unavailable=true;await login();
  await page.getByText(/Connexion D1 impossible/).waitFor();
  unavailable=false;await login();
  await page.getByText('Session D1 confirmée.',{exact:true}).waitFor();
  await page.getByText('Page 1 · 50 personnes affichées').waitFor();
  await page.getByRole('button',{name:'Page suivante'}).click();
  await page.getByText('Page 2 · 50 personnes affichées').waitFor();
  await page.getByRole('button',{name:'Page précédente'}).click();
  await page.getByText('Page 1 · 50 personnes affichées').waitFor();
  await page.getByRole('searchbox',{name:'Rechercher une personne'}).fill('Camille');
  await page.getByRole('button',{name:'Rechercher'}).click();
  await page.getByText('Page 1 · 1 personnes affichées').waitFor();
  await page.getByRole('heading',{name:'Types de membres et autorisations'}).waitFor();
  await page.getByRole('heading',{name:'Rapprochements d’identité (validation manuelle)'}).waitFor();
  failDirectory=true;
  await page.getByRole('button',{name:'Rechercher'}).click();
  await page.getByText(/Recherche indisponible/).waitFor();
  failDirectory=false;
  await page.getByRole('button',{name:'Espaces des célébrations'}).click();
  await page.getByText(/Chargement impossible/).waitFor();
  assert.equal(await page.getByRole('button',{name:'Enregistrer les espaces'}).isDisabled(),true);
  assert.equal(await page.getByRole('button',{name:'Créer dans le brouillon'}).count(),0);
  await page.getByText('Chargez les espaces canoniques avant toute modification.').waitFor();
  // M012-D real writes are covered by the actual workerd/D1/R2 browser test.
  for(const key of ['pages','footer','celebrations','media','guide']){
   await tab(key).click();assert.equal(await tab(key).evaluate(el=>el.classList.contains('active')),true);
   assert.equal(await page.locator('#save-btn').isVisible(),true);
  }
  await tab('members-spaces').click();
  assert.equal(await page.getByRole('button',{name:'Enregistrer les espaces'}).isDisabled(),true);
  assert.equal(await page.locator('#save-btn').isVisible(),false);
  await page.getByRole('button',{name:'Contacts et autorisations'}).click();
  denyDirectory=true;
  await page.getByRole('button',{name:'Rechercher'}).click();
  await page.locator('.member-session-box').getByText('Non connecté à D1',{exact:true}).waitFor();
  denyDirectory=false;await login();
  await page.getByText('Page 1 · 50 personnes affichées').waitFor();
  await page.getByRole('button',{name:'Se déconnecter de D1'}).click();
  await page.getByText('Déconnexion D1 confirmée.').waitFor();
  assert.equal(await page.getByRole('searchbox',{name:'Rechercher une personne'}).count(),0);
  assert.equal(requests.some(r=>r.path==='/api/admin/member-directory'&&r.method==='POST'),false);
  assert.ok(requests.filter(r=>r.path==='/api/admin/member-directory').every(r=>r.auth?.startsWith('Bearer ')));
  assert.equal(await page.evaluate(()=>Object.keys(localStorage).some(k=>/token|session/i.test(k))),false);
  const overflow=await page.evaluate(()=>document.documentElement.scrollWidth-document.documentElement.clientWidth);
  assert.ok(overflow<=1,'overflow at '+width+': '+overflow);
  assert.deepEqual(errors,[],'browser JS errors at '+width);
  await page.getByRole('button',{name:'Espaces des célébrations'}).click();
  assert.equal(await page.getByRole('button',{name:'Enregistrer les espaces'}).isDisabled(),true);
  await page.close();
  console.log('M012B_REAL_EDITOR_CHROMIUM_'+width+'_PASS');
 }
}finally{await browser?.close();await new Promise(resolve=>server.close(resolve));}
